{"components/scenario_prefixes/work.py": "def compute(payload):
    """输出 [信号历史,该完整叶的权重或 null]，去重生成所有非空前缀，按历史字典序排列。"""
    scenarios = payload["scenarios"]
    # 每条完整路径不同，因此完整信号序列唯一对应一个叶权重。
    leaf_weight = {tuple(s["signals"]): s["weight"] for s in scenarios}
    prefixes = set()
    for s in scenarios:
        signals = s["signals"]
        for i in range(1, len(signals) + 1):
            prefixes.add(tuple(signals[:i]))
    result = []
    for p in sorted(prefixes):
        result.append([list(p), leaf_weight.get(p)])
    return result
"}

{"components/menu_eligibility/work.py": "def compute(payload):
    """每个到货信号映射至可供菜品 ID，保持 recipes 顺序，检查难度、原料可得性和过敏限制。"""
    recipes = payload["recipes"]
    groups = payload["groups"]
    delivery = payload["delivery"]

    # 任一群体禁用的配料集合
    banned = set()
    for _, _, banned_list, _ in groups:
        banned.update(banned_list)

    result = {}
    for signal, available in delivery.items():
        available_set = set(available)
        eligible = []
        for recipe in recipes:
            if recipe["difficulty"] > 4:
                continue
            ingredients = recipe["ingredients"]
            if any(ing in banned for ing in ingredients):
                continue
            if all(ing in available_set for ing in ingredients):
                eligible.append(recipe["id"])
        result[signal] = eligible
    return result
